def write(h):
 table,sec,quiz,w=h['table'],h['sec'],h['quiz'],h['w'];E=[];P=[]
 E.append(sec('e-1','Biologie : définir ce que le dosage peut montrer', '''<p>La thyréostimuline est un examen de fonction, pas un test d’exclusion du cancer. L’interpréter avec l’intervalle du laboratoire, l’âge, la grossesse et les traitements. En cas de résultat discordant, rechercher une interférence, notamment la biotine, et préciser les conditions de prélèvement plutôt que conclure immédiatement à une modification tumorale [S3, S14].</p><p>La thyroglobuline et ses anticorps servent à un suivi différencié dans un contexte défini. Elle n’est pas un dosage de dépistage de tout nodule. La calcitonine s’inscrit dans l’évaluation d’un cancer médullaire suspecté ; aucune valeur seuil universelle diagnostique n’est donnée ici. La méthode, le contexte et les recommandations de l’équipe importent [S3–S5].</p><p>Avant ou après chirurgie, les dosages du calcium et de la parathormone peuvent contribuer à identifier une atteinte parathyroïdienne. Paresthésies, crampes ou tétanie après thyroïdectomie font rechercher une hypocalcémie. Une valeur isolée ou un schéma ambigu extrait d’un guide ne devient pas un ordre universel d’arrêter le calcium [S4].</p>''','Le nom du dosage doit être suivi de la question qu’il résout. Fonction, marqueur tumoral et complication ne sont pas la même chose [S3–S5].'))
 E.append(sec('e-2','Échographie, prélèvement et concordance', '''<p>L’échographie doit décrire les nodules et les aires ganglionnaires pertinentes. Un score de risque n’est pas un diagnostic histologique. La décision de ponction dépend du score, de la taille et des exceptions cliniques. La cytologie se lit avec le prélèvement réellement réalisé, sa qualité et la concordance échographique [S3, S4].</p>'''+table(['Risque échographique adulte','Seuil de taille du guide ETA2023','Précision'],[['EU-TIRADS3','Ponction au-delà de20mm.','Faible risque ne signifie pas risque nul.'],['EU-TIRADS4','Au-delà de15mm.','Ne pas confondre catégorie et stade.'],['EU-TIRADS5','Au-delà de10mm.','Ganglion ou extension suspects peuvent modifier la décision.']])+'''<p>Une ponction non diagnostique appelle une stratégie adaptée ; selon le cas, une nouvelle ponction ou une microbiopsie peut être discutée. En cas de suspicion anaplasique ou lymphomateuse, organiser rapidement du tissu adéquat et les analyses nécessaires. Les catégories britanniques Thy de NICE et les catégories Bethesda ne sont pas deux libellés automatiquement interchangeables [S3–S5].</p>''','La qualité et la concordance du prélèvement comptent. Seuils adultes et exceptions ne se transposent pas directement à l’enfant [S3, S8].'))
 E.append(sec('e-3','Imagerie d’extension : une indication précise', '''<p>Une imagerie en coupe est choisie selon suspicion d’extension locale, ganglionnaire ou distante. NICE la propose notamment dans des maladies plus étendues ; elle n’est pas une étape identique obligatoire pour chaque petit cancer différencié intrathyroïdien. La question et l’histotype guident la modalité [S4, S5].</p><p>Le cancer anaplasique nécessite un bilan rapide de l’étendue ; la S3 discute échographie, tomodensitométrie, imagerie par résonance magnétique et imagerie métabolique appropriées. Une suspicion d’atteinte cérébrale appelle une imagerie adaptée. La possibilité d’une préparation nucléaire future ne doit pas faire ignorer le besoin d’une imagerie urgente actuelle [S4].</p><p>Le contraste iodé peut modifier la fixation d’un radioiode ultérieur. Relever date et produit puis coordonner avec la médecine nucléaire. La FI Curium donne des délais indicatifs, notamment six à huit semaines après certains contrastes hydrosolubles ; ce délai ne devient pas une règle d’interdire toute imagerie iodée urgente [S15].</p>''','Un examen d’extension doit répondre à une question qui influence la conduite. Documenter aussi ses conséquences sur le calendrier nucléaire [S4, S5, S15].'))
 E.append(sec('e-4','Quatre exercices de décision', '''<p>Chaque vignette suivante est fictive. Les réponses vérifient un raisonnement ; elles ne constituent pas des données de patients ni une prescription [S3, S4, S9, S15].</p>'''+quiz('Fonction normale et nodule', [('Une fonction hormonale normale exclut une tumeur maligne.',False),('La fonction et la nature du tissu doivent être évaluées séparément.',True)],'La thyréostimuline renseigne sur la fonction globale. Le risque tumoral dépend notamment de la clinique, de l’image et du prélèvement adapté [S3, S4].')+quiz('Cancer médullaire et phéochromocytome associé', [('Opérer la thyroïde sans tenir compte du phéochromocytome.',False),('Prendre en charge le phéochromocytome avant l’opération thyroïdienne.',True)],'Les catécholamines peuvent rendre l’intervention dangereuse. L’évaluation de prédisposition et des tumeurs associées change l’ordre des soins [S4].')+quiz('Cancer différencié à quarante ans avec ganglion, sans métastase distante', [('L’atteinte ganglionnaire impose toujours le stade quatre.',False),('La classification anatomique de neuvième édition le classe dans le groupe un à cet âge.',True)],'Avant cinquante-cinq ans, la fiche européenne classe une forme différenciée sans métastase distante au stade un ; le ganglion reste pertinent pour le risque et la prise en charge [S9].')+quiz('Conversion d’activité radioactive', [('Un virgule un gigabecquerel vaut onze mégabecquerels.',False),('Un virgule un gigabecquerel vaut mille cent mégabecquerels.',True)],'Un gigabecquerel vaut mille mégabecquerels. La conversion ne choisit ni l’indication ni l’activité individuelle [S15, S21].'),'Comprendre pourquoi la réponse est correcte compte davantage que reconnaître une expression. Préserver âge, histotype, unités et population [S3, S4, S9, S15].'))
 lt=table(['Question','Repère FI février2023','Limite clinique'],[['Produit et voie','Euthyrox, comprimés25–200microgrammes ; voie orale.','Vérifier présentation et prescription.'],['Après thyroïdectomie pour cancer','Plage150–300microgrammes par jour dans la FI.','Pas une dose initiale universelle ; objectif de thyréostimuline et risques individuels.'],['Prise','À jeun, au moins30minutes avant le petit déjeuner.','Régularité et interactions modifient l’exposition.'],['Absorption','Calcium, fer ou aluminium au moins2heures après ; résines4–5heures après.','Ne pas remplacer ces délais par une règle inventée commune à tous les médicaments.'],['Fonctions d’organes','Pharmacocinétique rénale/hépatique non étudiée.','Aucune adaptation numérique universelle déduite.']])
 P.append(sec('p-1','Lévothyroxine : substitution et suppression', '''<p>Euthyrox, FI suisse de février2023, est une lévothyroxine orale. Après thyroïdectomie, remplacer la production absente et supprimer la thyréostimuline dans certaines formes différenciées sont deux objectifs à distinguer. La même molécule ne rend pas le même objectif approprié à tous les histotypes [S4, S14].</p>'''+lt+'''<p>La dose est individualisée selon besoin, réponse, âge, état cardiaque et risque osseux. La plage de FI n’impose pas150microgrammes comme première dose à toute personne. Les symptômes de surtraitement et les résultats biologiques doivent être évalués ; une suppression plus intense n’est pas automatiquement meilleure. Une maladie cardiaque ou une insuffisance surrénalienne non traitée doit être considérée selon les contre-indications et précautions du produit [S4, S14].</p><p>La biotine peut perturber les analyses. Calcium, fer, résines, aliments et autres médicaments peuvent modifier l’exposition ; préciser les prises avant d’augmenter une dose devant une valeur inattendue. La substitution nécessaire pendant une grossesse est poursuivie et surveillée, avec réévaluation des besoins ; elle n’est pas remplacée par un arrêt pour protéger le fœtus [S14].</p>''','Microgramme, dose prescrite et objectif biologique sont distincts. La FI fournit une plage, la situation clinique détermine la dose [S4, S14].'))
 radio=table(['Élément','FI Curium juillet2022','Interprétation'],[['Produit','Sodium iodide (I-131) capsule T ; oral.','Capsule thérapeutique, pas préparation diagnostique interchangeable.'],['Présentation','37–7400mégabecquerels à la date de calibration.','Plage de présentation, pas dose de chaque patient.'],['Ablation de reliquat après chirurgie','1100–3700mégabecquerels selon reliquat, fixation et contexte.','Pas schéma universel de toute maladie métastatique.'],['Rein ou enfant','Évaluation individuelle et dosimétrie.','Ne pas appliquer une réduction fixe inventée.'],['Grossesse et allaitement','Contre-indications ; sevrage au moins8semaines avant, sans reprise pour cet enfant.','Informer et vérifier avant administration.']])
 P.append(sec('p-2','Iode131 : objectif, activité et radioprotection', '''<p>La FI suisse Curium de juillet2022 doit être liée à l’objectif nucléaire. Le guide européen distingue ablation d’un reliquat, adjuvant et traitement d’une maladie connue. La décision de traiter n’est pas donnée par le seul fait qu’une capsule existe dans une activité particulière [S7, S15].</p>'''+radio+'''<p>Grossesse, allaitement et certaines difficultés de déglutition ou lésions digestives contre-indiquent cette capsule. Le service vérifie la capacité de l’avaler, les interactions, la fonction rénale et la préparation. Gonflement ou inflammation peuvent être dangereux au voisinage de structures critiques ; le traitement n’est pas une méthode de décompression immédiate [S15].</p><p>Pour le projet de grossesse, la FI comporte un conseil de six à douze mois et précise douze mois de contraception dans le contexte malin. Le calendrier est clarifié avec l’équipe plutôt que choisir silencieusement le nombre le plus court. Après traitement, les précautions de proximité, d’hygiène et de sortie sont individualisées. La directive suisse de radioprotection prévoit notamment une filière hospitalière dès200mégabecquerels, avec exceptions ambulatoires encadrées ; le fractionnement pour éviter l’hospitalisation n’est pas autorisé [S15, S21].</p>''','Le radioiode exige une indication, une activité individualisée, une préparation et des consignes écrites. La conversion d’unités ne remplace aucune de ces décisions [S7, S15, S21].'))
 rh=table(['Étape','FI Thyrogen juin2023','Point de sécurité'],[['Injection','0,9mg par voie intramusculaire, puis0,9mg24heures après.','Voie exclusivement intramusculaire, pas intraveineuse.'],['Radioiode','24heures après la seconde injection.','Planifier avec le service nucléaire.'],['Thyroglobuline stimulée','Prélèvement72heures après la seconde injection.','Anticorps et méthode restent pertinents.'],['Préablation','Avec1,1–3,7gigabecquerels après chirurgie quasi totale ou totale, sans métastase distante.','Ne pas élargir automatiquement à une maladie métastatique.']])
 P.append(sec('p-3','Thyrogen : une stimulation avec un calendrier propre', '''<p>Thyrogen contient de la thyréostimuline recombinante. La FI suisse de juin2023 décrit les indications et le calendrier ci-dessous. Une recommandation qui évoque un usage hors indication ne transforme pas cet usage en indication suisse, notamment pour la préablation avec métastases distantes [S5, S7, S16].</p>'''+rh+'''<p>Le produit est contre-indiqué pendant la grossesse et ne doit pas être utilisé pendant l’allaitement. Une insuffisance rénale terminale peut prolonger l’exposition ; aucune règle numérique d’adaptation n’est établie. L’activité de radioiode doit également tenir compte du terrain. L’emploi pédiatrique est exceptionnel et les résultats adultes ne donnent pas un schéma automatique à tout enfant [S16].</p><p>La stimulation peut provoquer un gonflement de tissu tumoral, important près des voies aériennes, du cerveau, de la moelle ou des orbites. Les risques cardiaques sont évalués. Cette précaution explique la planification spécialisée ; elle ne justifie pas d’inventer dans ce cours une dose préventive de corticoïde [S16].</p>''','Deux injections intramusculaires et des délais distincts : vérifier indication, voie et calendrier avant les calculs [S16].'))
 lenv=table(['Situation','FI Lenvima septembre2025','Limite'],[['Indication thyroïdienne','Cancer différencié progressif, avancé ou métastatique, réfractaire au radioiode.','Pas tout cancer stable ayant reçu du radioiode.'],['Dose adulte','24mg par voie orale une fois par jour, avec ou sans nourriture.','Deux capsules10mg et une4mg ; vérifier la prescription.'],['Paliers de réduction','20mg, puis14mg, puis10mg par jour.','Ne pas sauter automatiquement au palier14mg.'],['Insuffisance rénale sévère','14mg par jour dans le contexte différencié ; terminale non recommandée.','Ne pas transposer une dose d’un autre cancer.'],['Insuffisance hépatique','Child A/B sans adaptation ; Child C14mg par jour pour cette indication.','Doses d’autres indications différentes.']])
 P.append(sec('p-4','Lenvatinib : indication progressive et surveillance', '''<p>Lenvima, FI suisse de septembre2025, est étudié ici uniquement dans son indication de cancer différencié. Le statut réfractaire au radioiode ne suffit pas à lui seul à imposer un inhibiteur : progression, symptômes, menace et possibilités locales sont discutés au préalable [S4, S17].</p>'''+lenv+'''<p>Contrôler l’hypertension avant le début, puis la surveiller à une semaine, toutes les deux semaines pendant les deux premiers mois et ensuite mensuellement selon la FI. Protéinurie, déshydratation, fonction rénale, bilan hépatique, électrolytes et risque cardiaque demandent des contrôles. Une invasion proche de gros vaisseaux ou des voies digestives rend particulièrement pertinentes les complications hémorragiques, fistules et perforations [S17].</p><p>La FI prévoit une interruption six jours avant une chirurgie élective et une reprise après appréciation de la cicatrisation. Grossesse et allaitement sont contre-indiqués ; contraception pendant le traitement et un mois après, avec méthode non hormonale supplémentaire si contraception orale. La sécurité et l’efficacité ne sont pas établies de2à18ans et le produit ne doit pas être utilisé avant2ans ; aucune dose pédiatrique de cancer thyroïdien n’est déduite ici [S17].</p>''','24mg et ses paliers appartiennent à une indication précise. Hypertension, protéinurie, saignement et cicatrisation font partie du choix et du suivi [S17].'))
 sel=table(['Question','FI Retsevmo décembre2025','Précision'],[['Papillaire','Adulte, fusion RET, maladie avancée nécessitant un traitement systémique après progression sous traitement préalable incluant radioiode.','Ne pas élargir à toute histologie ou tout enfant.'],['Médullaire','Mutation RET, avancé, adulte et adolescent dès12ans.','Mutation et fusion ne sont pas synonymes.'],['Dose selon poids','Moins50kg :120mg deux fois par jour ; au moins50kg :160mg deux fois par jour.','Prises orales espacées d’environ12heures.'],['Foie sévèrement atteint','80mg deux fois par jour.','Vérifier la définition et l’ensemble des ajustements de la FI.'],['Rein','Pas d’adaptation pour un débit de filtration glomérulaire estimé d’au moins15mL/min/1,73m² ; stade terminal/dialyse sans données.','Ne pas inventer une dose de dialyse.'],['Médicaments de l’acidité gastrique','Inhibiteur de pompe : prendre avec nourriture ; antagoniste H2 : Retsevmo2heures avant.','Antiacide2heures avant ou après ; pas délai supplémentaire inventé.']])
 P.append(sec('p-5','Selpercatinib : RET, indication et interactions', '''<p>Retsevmo, FI suisse de décembre2025, impose de préciser l’altération et la population. Les autorisations ou recommandations étrangères de première ligne ne remplacent pas les conditions du libellé suisse. Le tableau ne remplace pas la vérification de la molécule et des traitements antérieurs [S18].</p>'''+sel+'''<p>Éviter autant que possible les inhibiteurs puissants ou modérés de CYP3A et les inducteurs pertinents ; les ajustements dépendent du niveau d’inhibition et de la dose initiale. Par exemple, un inhibiteur puissant conduit dans la FI à40mg deux fois par jour à partir de120mg, ou80mg deux fois par jour à partir de160mg. Il ne faut pas appliquer une réduction unique à toute interaction [S18].</p><p>Surveiller pression artérielle, électrocardiogramme, électrolytes, fonction hépatique et thyroïdienne selon les délais du produit. Une pneumopathie, un saignement ou une hypertension importante appelle une évaluation et une adaptation. La créatinine peut aussi augmenter par effet sur sa sécrétion tubulaire ; cela n’autorise pas à ignorer une véritable atteinte rénale [S18].</p><p>Interrompre au moins sept jours avant une chirurgie élective ; après chirurgie majeure, attendre au moins deux semaines et une cicatrisation adéquate. Chez l’adolescent, les effets sur les cartilages de croissance demandent une attention particulière. La grossesse relève d’une appréciation spécialisée du bénéfice et du risque ; l’allaitement est évité pendant le traitement et pendant deux semaines après. Les mesures de contraception concernent les deux sexes et se poursuivent deux semaines après [S18].</p>''','Un résultat RET ne suffit pas : vérifier mutation ou fusion, âge, poids, indication, interactions et chirurgie prévue [S18].'))
 pair=table(['Élément','FI suisses Tafinlar et Mekinist, août2026','Piège'],[['Indication agnostique adulte','Tumeur solide BRAF V600E non résécable ou métastatique, progression après traitement préalable et absence d’alternative satisfaisante.','Ne certifie pas toute utilisation néoadjuvante première ligne dans l’anaplasique.'],['Dabrafénib','150mg deux fois par jour par voie orale.','Dose adulte, pas tableau pédiatrique de gliome.'],['Tramétinib','2mg une fois par jour par voie orale.','Deux médicaments, deux fréquences.'],['Repas','Au moins1heure avant ou2heures après un repas.','Coordonner les prises selon la prescription.'],['Fièvre','Dès38°C, interrompre les deux partenaires et rechercher notamment une infection.','Ne pas interrompre seulement le dabrafénib.'],['Fonctions d’organes','Pas d’ajustement pour rein léger/modéré ou foie léger ; précautions et données limitées au-delà.','Aucune réduction numérique universelle inventée.']])
 P.append(sec('p-6','Dabrafénib et tramétinib : deux partenaires à surveiller', '''<p>Les deux FI suisses d’août2026 comportent une indication agnostique conditionnelle chez l’adulte. La S3 discute l’association en néoadjuvant pour certaines formes anaplasiques non résécables BRAF V600E. Cette recommandation et les conditions suisses ne sont pas confondues : l’utilisation concrète exige une vérification spécialisée de l’indication et de l’accès [S4, S19, S20, S29].</p>'''+pair+'''<p>La pyrexie peut s’accompagner de frissons, déshydratation, hypotension et insuffisance rénale. La FI demande l’interruption des deux médicaments dès38°C, une recherche d’infection et un traitement de soutien approprié. La reprise relève du prescripteur après au moins24heures sans symptômes, à dose identique ou réduite selon récidive et gravité. Ce n’est pas un conseil d’autogestion isolée d’une fièvre chez une personne traitée pour cancer [S19, S20].</p><p>Évaluer la fraction d’éjection ventriculaire gauche avant traitement, à un mois puis environ tous les trois mois. Contrôler le foie toutes les quatre semaines pendant six mois, puis selon la clinique. Une nouvelle anomalie visuelle ou respiratoire nécessite une évaluation rapide ; rétinopathie, atteinte cardiaque, pneumopathie, saignement et réactions cutanées graves font partie des risques [S19, S20].</p><p>Le dabrafénib a de nombreuses interactions enzymatiques et peut réduire l’efficacité des contraceptifs hormonaux. Une méthode alternative est nécessaire ; les mesures contraceptives de l’association tiennent compte du délai d’au moins seize semaines après le tramétinib. Grossesse et allaitement exigent une vérification spécialisée ; les indications pédiatriques de gliome dès un an ne créent pas une dose de cancer thyroïdien pédiatrique [S19, S20].</p>''','Une association n’est pas un seul médicament : voies, fréquences, interactions et conduite devant la fièvre doivent rester explicites [S19, S20].'))
 P.append(sec('p-7','Prescription, autorisation et remboursement', '''<p>La FI décrit un produit et son autorisation ; une recommandation clinique répond à une population et à une question ; la liste des spécialités et ses limitations concernent la prise en charge. Ces documents doivent être lus ensemble sans supposer que l’un remplace les autres [S28, S29].</p><p>Les conditions d’un usage hors indication ou hors limitation et les possibilités de remboursement exceptionnel sont appréciées individuellement. Le cadre OFSP exige notamment l’accord spécial de l’assureur après consultation du médecin-conseil. L’accès urgent à une équipe oncologique ne doit pas être assimilé à une garantie financière automatique [S29].</p><p>Aucune limitation individuelle actuelle de chacun des médicaments n’est certifiée dans cette lecture ciblée. Les FIs sont datées ; cela ne certifie pas le stock, une disponibilité locale immédiate ou le financement d’un schéma pour une personne donnée. Expliquer cette distinction permet de discuter le plan concrètement sans annoncer une promesse non vérifiée [S14–S20, S28, S29].</p>''','Vérifier la clinique, le libellé du produit et l’accès réel. Ne pas transformer une source étrangère ou une cible moléculaire en accord suisse automatique [S18–S20, S28, S29].'))
 sor=table(['Élément','FI Nexavar novembre2023','Limite'],[['Indication','Cancer différencié progressif, avancé ou métastatique, réfractaire au radioiode.','Pas un traitement de tout nodule ni de toute maladie stable.'],['Dose orale','400mg deux fois par jour, soit800mg par jour.','À jeun ou avec un repas léger pauvre en graisses.'],['Réductions thyroïdiennes','600mg par jour en deux prises, puis400mg par jour, puis200mg par jour.','Ne pas copier directement le palier d’un autre type de cancer.'],['Rein','Pas d’adaptation légère, modérée ou sévère selon la FI ; dialyse sans expérience.','Surveiller hydratation et électrolytes ; absence de réduction ne signifie pas absence de risque.'],['Foie et enfant','Child A/B sans adaptation ; Child C sans expérience. Enfant et adolescent non prévus.','Aucune dose Child C ou pédiatrique inventée.']])
 P.append(sec('p-8','Sorafénib : dose, peau, calcium et fonction thyroïdienne', '<p>Nexavar, FI suisse de novembre2023, conserve une indication dans le cancer différencié progressif réfractaire au radioiode. Il ne faut pas comparer directement les résultats d’essais différents pour affirmer une supériorité individuelle sur un autre inhibiteur [S6, S30].</p>'+sor+'<p>Rechercher et surveiller syndrome main-pied, hypertension, diarrhée ou déshydratation, atteinte cardiaque, saignement et troubles des électrolytes. La FI souligne le contrôle de la calcémie dans le cancer thyroïdien, notamment en cas d’antécédent d’hypoparathyroïdie, et le contrôle mensuel de la thyréostimuline avec adaptation de la substitution si nécessaire [S30].</p><p>Le risque de saignement rend importantes les infiltrations trachéales, bronchiques ou œsophagiennes, qui doivent être traitées localement avant l’administration selon la FI. Une chirurgie majeure nécessite une interruption préventive et une appréciation de la cicatrisation avant reprise ; aucun délai numérique non donné par cette FI n’est ajouté ici [S30].</p><p>Les inducteurs enzymatiques peuvent diminuer l’exposition ; les dérivés de la coumarine et d’autres associations exigent leur propre surveillance. Le médicament ne doit pas être administré pendant une grossesse sauf nécessité absolue ; contraception fiable pendant le traitement et absence d’allaitement sont requises selon le texte. Aucun schéma pédiatrique ou de dialyse n’est déduit [S30].</p>', 'Vérifier les paliers propres au cancer différencié et surveiller peau, pression, calcium et fonction thyroïdienne [S30].'))
 cabo=table(['Élément','FI Cabometyx décembre2025','Précision'],[['Indication thyroïdienne','Adulte, cancer différencié avancé ou métastatique, réfractaire ou non éligible au radioiode, progression pendant ou après un traitement ciblant le facteur de croissance de l’endothélium vasculaire.','Cette FI n’est pas une autorisation de tout cabozantinib dans le médullaire.'],['Monothérapie orale','60mg une fois par jour ; réductions40mg puis20mg par jour.','Ne pas copier la dose d’une association destinée au cancer rénal.'],['Repas','Ne rien manger pendant au moins2heures avant et1heure après.','Comprimés entiers.'],['Foie','Léger : pas d’ajustement ; modéré : aucune recommandation numérique possible ; sévère : non recommandé.','Ne pas inventer un palier Child B.'],['Rein et enfant','Léger/modéré : prudence ; sévère : non recommandé. Utilisation pédiatrique non autorisée.','Pas dose enfant ni dose rénale sévère proposée.']])
 P.append(sec('p-9','Cabozantinib : produit et ligne thérapeutique', '<p>Cabometyx, FI suisse de décembre2025, est décrit dans son indication de cancer différencié après un traitement ciblant la voie du facteur de croissance vasculaire. La forme pharmaceutique, les indications et les populations d’un autre produit de cabozantinib ne sont pas assimilées à cette fiche [S31].</p>'+cabo+'<p>Surveiller précocement pression artérielle, protéines urinaires, calcium et autres électrolytes, fonction hépatique, peau et symptômes digestifs. Fistules, perforations, hémorragies, thromboses et défaut de cicatrisation sont des risques importants. Un examen dentaire et une hygiène buccale adaptée participent à la prévention des complications maxillaires [S31].</p><p>Dans la mesure du possible, la FI demande un arrêt au moins28jours avant une chirurgie programmée, y compris dentaire ; la reprise repose sur une cicatrisation adéquate. Les inhibiteurs et inducteurs enzymatiques ainsi que les autres traitements concomitants doivent être vérifiés ; le calendrier d’une autre molécule n’est pas transposé [S31].</p><p>Éviter la grossesse, sauf nécessité absolue évaluée ; contraception efficace pour les deux sexes et partenaires pendant le traitement et au moins quatre mois après. La contraception orale demande une méthode supplémentaire. L’allaitement n’a pas lieu pendant le traitement ni pendant au moins quatre mois après [S31].</p>', 'Cabometyx :60mg en monothérapie dans une indication précise, paliers40puis20mg, repas et chirurgie avec délais propres au produit [S31].'))
 van=table(['Élément','FI Caprelsa avril2025','Point de sécurité'],[['Indication','Adulte, cancer médullaire agressif et symptomatique avec mutation RET, non opérable, avancé ou métastatique.','Pas indication suisse universelle de tout cancer médullaire.'],['Dose orale','300mg une fois par jour, avec ou sans repas ; paliers200puis100mg.','Pas dose pédiatrique.'],['Clairance de la créatinine','De30mL/min inclus à moins de50mL/min : dose initiale200mg.','Clairance inférieure à30mL/min : contre-indication de la FI.'],['Foie','Déconseillé si bilirubine supérieure à1,5fois la limite normale.','Données insuffisantes, pas réduction inventée.'],['Électrocardiogramme et électrolytes','Avant traitement, puis2–4semaines,8–12semaines et tous les3mois.','Plus fréquent si besoin ; contrôler calcium, magnésium et potassium.']])
 P.append(sec('p-10','Vandétanib : indication RET et risque électrique cardiaque', '<p>Caprelsa, FI suisse d’avril2025, exige une forme médullaire agressive et symptomatique avec mutation RET dans la population indiquée. Ce libellé n’est pas remplacé par une indication étrangère plus large ou pédiatrique. Le choix avec les autres options relève de l’équipe spécialisée [S32].</p>'+van+'<p>Le syndrome congénital du QT long, l’insuffisance rénale sévère et l’allaitement sont contre-indiqués. La rubrique posologique dit aussi « déconseillé » pour le rein sévère ; cela n’annule pas la contre-indication explicite. Un intervalle corrigé durablement supérieur à480millisecondes empêche l’instauration selon la FI ; une valeur d’au moins500millisecondes impose l’arrêt, avec éventuelle reprise médicale seulement après correction durable et réévaluation [S32].</p><p>Éviter les associations qui allongent cet intervalle et rechercher les interactions. Une diarrhée peut aggraver la perte d’électrolytes et le risque d’arythmie. Surveiller aussi pression, peau/photosensibilité, foie, rein et symptômes pulmonaires ; une suspicion de pneumopathie interstitielle impose l’interruption et l’évaluation [S32].</p><p>La grossesse exige une appréciation du bénéfice et du risque ; contraception fiable pendant le traitement et au moins quatre mois après pour les personnes concernées. Avant une chirurgie, envisager une interruption d’au moins quatre semaines selon la balance individuelle ; ne pas administrer pendant au moins deux semaines après chirurgie majeure et attendre une cicatrisation suffisante [S32].</p>', 'Le risque d’arythmie exige une sélection initiale, des contrôles et une lecture des contre-indications ; la dose rénale ne contourne pas une contre-indication [S32].'))
 return E,P,{'lt4':lt,'radio':radio,'rh':rh,'lenv':lenv,'sel':sel,'pair':pair,'sor':sor,'cabo':cabo,'van':van}
